/**
 * A batch of room-list changes, carrying the sequence number its ordering
 * depends on.
 */
public struct RoomDiffEnvelope {
    public var channel: String
    public var subject: String
    /**
     * Monotonic per subject. A host that reorders these corrupts the list —
     * see `supermessage_core::event`'s note on delivery order.
     */
    public var seq: UInt64
    public var ops: [RoomDiffOp]

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(channel: String, subject: String, 
        /**
         * Monotonic per subject. A host that reorders these corrupts the list —
         * see `supermessage_core::event`'s note on delivery order.
         */seq: UInt64, ops: [RoomDiffOp]) {
        self.channel = channel
        self.subject = subject
        self.seq = seq
        self.ops = ops
    }
}



extension RoomDiffEnvelope: Equatable, Hashable {
    public static func ==(lhs: RoomDiffEnvelope, rhs: RoomDiffEnvelope) -> Bool {
        if lhs.channel != rhs.channel {
            return false
        }
        if lhs.subject != rhs.subject {
            return false
        }
        if lhs.seq != rhs.seq {
            return false
        }
        if lhs.ops != rhs.ops {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(channel)
        hasher.combine(subject)
        hasher.combine(seq)
        hasher.combine(ops)
