/**
 * A failure the host can act on.
 *
 * The string fields on `Auth`, `Network`, `Store` and `Protocol` are called
 * `detail`, not `message`. UniFFI compiles this into a Kotlin exception
 * extending `kotlin.Exception`, which already declares `message`; a field of
 * the same name collides with it (`'message' hides member of supertype`,
 * plus overload-resolution ambiguity). Do not rename it back.
 */
public enum FfiError {

    
    
    /**
     * Credentials were refused, or the session is no longer valid. The host
     * should return to its sign-in screen.
     */
    case Auth(detail: String
    )
    /**
     * The homeserver could not be reached. Worth retrying.
     */
    case Network(detail: String
    )
    /**
     * The credential store or the local database refused. On iOS this is
     * also what a locked device looks like — the Data Protection keychain is
     * unreadable until first unlock, which is a state to wait out rather
     * than an error to report.
     */
    case Store(detail: String
    )
    /**
     * Anything else: a malformed response, an unexpected state.
     */
    case Protocol(detail: String
    )
    /**
     * There is no session yet. The host asked for something that needs one.
     */
    case NotReady
    /**
     * The focused room moved while the request was in flight. Not a failure
     * of the request so much as of its timing — the host may reissue it
     * against the room now focused.
     */
    case RoomChanged(requested: String, focused: String
    )
    /**
     * The file is larger than the server will take. Carries both numbers so
     * a host can say "12MB, limit 10MB" rather than "too large".
     */
    case AttachmentTooLarge(bytes: UInt64, limit: UInt64
    )
    /**
     * The staged attachment token is unknown — already sent, already
     * discarded, or from a previous run.
     */
    case UnknownAttachment
    /**
     * The space id is not one this account is in.
     */
    case UnknownSpace(spaceId: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Auth(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Network(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Store(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Protocol(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .NotReady
        case 6: return .RoomChanged(
            requested: try FfiConverterString.read(from: &buf), 
            focused: try FfiConverterString.read(from: &buf)
            )
        case 7: return .AttachmentTooLarge(
            bytes: try FfiConverterUInt64.read(from: &buf), 
            limit: try FfiConverterUInt64.read(from: &buf)
            )
        case 8: return .UnknownAttachment
        case 9: return .UnknownSpace(
            spaceId: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Auth(detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Network(detail):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Store(detail):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .Protocol(detail):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detail, into: &buf)
            
        
        case .NotReady:
            writeInt(&buf, Int32(5))
        
        
        case let .RoomChanged(requested,focused):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(requested, into: &buf)
            FfiConverterString.write(focused, into: &buf)
            
        
        case let .AttachmentTooLarge(bytes,limit):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(bytes, into: &buf)
            FfiConverterUInt64.write(limit, into: &buf)
            
        
        case .UnknownAttachment:
            writeInt(&buf, Int32(8))
        
        
        case let .UnknownSpace(spaceId):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(spaceId, into: &buf)
            
        }
    }
}


